def map_stages(df):
    STAGE_OUTCOME = {
        "Proposal": "Open",
        "Prospecting": "Open", 
        "Negotiation": "Open",
        "Closed Lost": "Lost",
        "Closed - Won": "Won"
    }
    df["Outcome"] = [STAGE_OUTCOME.get(s, s) for s in df["Stage"]]
    return df
